          "bn": "প্রভু যীশু খ্রীষ্ট, যিনি সেন্ট জুড থাডিউসকে প্রেরিত বলে ডাকেন, তাঁর মধ্যস্থতার মাধ্যমে আমাকে একটি জীবন্ত বিশ্বাস দান করুন যা আমার ভয় এবং সন্দেহকে জয় করে। সেন্ট জুড থাডিউস, আমাদের জন্য প্রার্থনা করুন।",
          "id": "Tuhan Yesus Kristus, yang memanggil Santo Yudas Thaddeus ke dalam kerasulan, berilah aku melalui perantaraannya iman yang hidup yang mengatasi ketakutan dan keraguanku. Santo Yudas Thaddeus, doakanlah kami.",
