          "ar": "أيها الروح القدس،  أعطني القوة حتى لا أستسلم في مواجهة الشدائد. أيها القديس جود الشجاع،  انضم إلي في يوم الانتظار والتمييز هذا.",
          "he": "ה' עֻזִּי וּמָגִנִּי, בּוֹ בָטַח לִבִּי וְנֶעֱזָרְתִּי.\nגַּם כִּי אֵלֵךְ בְּגֵיא צַלְמָוֶת לֹא אִירָא רָע כִּי אַתָּה עִמָּדִי.\nחַזֵּק אֶת רוּחִי בְּשָׁעָה זוֹ שֶׁל נִסָּיוֹן וּמַבְחָן, חַדֵּשׁ אֶת אֱמוּנָתִי וְהֱיֵה לִי לְצוּר מָעוֹז וּלְעֶזְרָה בְּצָרוֹת. אָמֵן.",
          "hi": "पवित्र आत्मा, मुझे विपरीत परिस्थितियों में हार न मानने की शक्ति दो। बहादुर संत जूड, प्रतीक्षा और विवेक के इस दिन पर मेरे साथ जुड़ें।",
          "zh": "圣灵，赐予我力量，让我在逆境中不放弃。勇敢的圣裘德，请与我一起度过这一等待和洞察的日子。",
          "la": "Spiritus Sanctus, dame la fortitudo ad non claudicar ante la adversidad. San Judas valeroso, acompáñame in esta jornada de espera et discernimiento.",
          "ja": "聖霊よ、逆境に直面しても諦めない力を賜りたまえ。勇敢な聖ジュードよ、この待ちと識別の日に私と一緒に来たりたまえ。",
          "bn": "পবিত্র আত্মা, আমাকে প্রতিকূলতার মুখে হাল ছেড়ে না দেওয়ার শক্তি দিন। সাহসী সেন্ট জুড, অপেক্ষা এবং বিচক্ষণতার এই দিনে আমার সাথে যোগ দিন।",
          "id": "Roh Kudus, beri aku kekuatan untuk tidak menyerah dalam menghadapi kesulitan. Saint Jude yang gagah berani, bergabunglah denganku pada hari penantian dan penegaSanto ini.",
          "ur": "روح القدس، مجھے طاقت دے کہ میں مصیبت کے وقت ہمت نہ ہاروں۔ بہادر سینٹ جوڈ، انتظار اور سمجھداری کے اس دن میرے ساتھ شامل ہوں۔",
