          "bn": "উদার সেন্ট জুড, যিনি অসহায়দের সাহায্য করেন, আমার এবং আমার জন্য শালীন কাজ, প্রভিডেন্স এবং অর্থনৈতিক ত্রাণের দরজা খুলে দেন।",
          "id": "Santo Yudas yang murah hati, yang membantu mereka yang tidak berdaya, membukakan pintu pekerjaan yang layak, pemeliharaan dan bantuan ekonomi bagi saya dan saya.",
