          "bn": "আপনাকে ধন্যবাদ, প্রভু, আমাদের প্রার্থনা শোনার জন্য! আপনাকে ধন্যবাদ, মহিমান্বিত সেন্ট জুড থাডিউস, আপনার অবিরাম সুরক্ষা এবং অবিরাম মধ্যস্থতার জন্য। আমীন।",
          "id": "Terima kasih, Tuhan, karena mendengarkan doa kami! Terima kasih, Santo Jude Thaddeus yang mulia, atas perlindungan Anda yang tiada henti dan syafaat Anda yang tak henti-hentinya. Amin.",
