      "bn": "দৃঢ় আশ্রয়, স্বর্গীয় পবিত্রতা এবং মাতৃসুলভ ঐশ্বরিক সুরক্ষা",
      "id": "Perlindungan Teguh, Kemurnian Surgawi, and Naungan Kudus",
      "ur": "ناقابل تسخیر پناہ گاہ، آسمانی پاکیزگی اور مادری شفاعت",
      "sw": "Ulinzi Usiotikisika, Usafi wa Mbinguni na Msaada Mkuu wa Kimama"
