          "de": "Om Devi Shailaputryai Namah. Möge mein Geist in Gelassenheit ruhen.",
          "ru": "Ом Деви Шаилапутряи Намах. Пусть мой разум покоится в спокойствии.",
          "ar": "أوم ديفي شيلابوترياي نامة. نرجو أن يستريح عقلي في صفاء.",
          "he": "נַהֲגֶה בִּזְהַר הַבּוֹרֵא הָעֶלְיוֹן, שֶׁמֶשׁ הַתּוֹדָעָה הָאֱלֹהִית הַמְּאִירָה אֶת הָעוֹלָמוֹת כֻּלָּם.\nיְהִי רָצוֹן שֶׁהָאוֹר הַנִּצְחִי יָאִיר אֶת מַחְשְׁבוֹתֵינוּ, יְטַהֵר אֶת לִבֵּנוּ וְיוֹבִילֵנוּ מֵחֹשֶׁךְ לְאוֹר, מִבַּעֲרוּת לִתְבוּנָה, וּמִתְּמוּתָה לְחַיֵּי נֵצַח.\nאוֹם שָׁלוֹם, שָׁלוֹם, שָׁלוֹם לְכָל הַבְּרִיאָה.",
          "hi": "वन्दे वाञ्छितलाभाय चन्द्रार्धकृतशेखराम्। वृषारूढां शूलधरां शैलपुत्रीं यशस्विनीम्॥ हे माँ शैलपुत्री! हमें आत्मबल, स्थिरता और भक्ति का वरदान दें।",
          "zh": "Om Devi Shailaputryai Namah。愿我的心灵安息。",
          "la": "Om Devi Shailaputryai Namah. Que mi mens descanse in serenidad.",
          "ja": "オーム・デヴィ・シャイラプトリアイ・ナマ。私の心が安らかに眠れますように。",
          "bn": "বন্দে বাঞ্ছিতলাভায় চন্দ্রার্ধকৃতশেখরাম্। বৃষারূঢ়াং শূলধরাং শৈলপুত্রীং যশস্বিনীম্॥ হে মা শৈলপুত্রী! আমাদের আত্মবিশ্বাস, স্থায়িত্ব ও পরম ভক্তি প্রদান করুন।",
