          "ar": "إيبورو إيبويا إيبوشيشي. شكرًا لك أولودوماري على الحياة والصحة والبركة. آش.",
          "he": "ה' עֻזִּי וּמָגִנִּי, בּוֹ בָטַח לִבִּי וְנֶעֱזָרְתִּי.\nגַּם כִּי אֵלֵךְ בְּגֵיא צַלְמָוֶת לֹא אִירָא רָע כִּי אַתָּה עִמָּדִי.\nחַזֵּק אֶת רוּחִי בְּשָׁעָה זוֹ שֶׁל נִסָּיוֹן וּמַבְחָן, חַדֵּשׁ אֶת אֱמוּנָתִי וְהֱיֵה לִי לְצוּר מָעוֹז וּלְעֶזְרָה בְּצָרוֹת. אָמֵן.",
          "hi": "इबोरु इबोया इबोशेशे। जीवन, स्वास्थ्य और आशीर्वाद के लिए ओलोडुमारे को धन्यवाद। ऐश।",
          "zh": "伊博鲁·伊博亚·伊博舍舍。感谢奥洛杜马雷赐予我生命、健康和祝福。阿什。",
          "la": "Iboru Iboya Ibosheshe. gratias Olodumare per la vita, la salus et la benedictio. Ashé.",
