          "bn": "হে ওরীশা! আমরা ভক্তিভরে আপনার আহ্বান করি। আমাদের জীবন থেকে সমস্ত বাধা দূর করে আত্মিক শান্তি, উত্তম স্বাস্থ্য ও নিরাপত্তা দান করুন। আশে।",
