          "ur": "اے اوریشا! ہم سچے دل سے آپ کا دھیان کرتے ہیں۔ ہمارے راستے سے تمام رکاوٹیں اور بلائیں دور فرما کر ہمیں قلبی سکون، صحت اور حفاظت عطا فرمائیں۔ آشے۔",
