          "hi": "अडोनाई रोई, लो एजसर। मैं किसी से नहीं डरता क्योंकि तू मेरे साथ है; आपकी छड़ी और आपके कर्मचारी मुझे प्रोत्साहन देते हैं।",
          "zh": "阿多奈·罗伊，洛·埃伊萨尔。我无所畏惧，因为你与我同在；你的杖和你的杖给了我鼓励。",
          "la": "Adonai Roí, Lo Ejsar. Nada temo quoniam Tú estás conmigo; tu vara et tu cayado me infunden aliento.",
