          "bn": "অ্যাডোনাই রোই, লো ইজসার। তুমি আমার সাথে আছো বলে আমি কিছুই ভয় পাই না; আপনার রড এবং আপনার কর্মীরা আমাকে উত্সাহ দেয়।",
