          "he": "בְּשֵׁם אֱלֹהִים, הָרַחֲמָן וְהָרַחוּם.\nשֶׁבַח וְהוֹדָיָה לַאלֹהִים, רִבּוֹן כָּל הָעוֹלָמִים.\nאָנָּא אֱלֹהַי, סְלַח לִי עַל חֲטָאַי, הַסֵּר מִלִּבִּי כָּל דְּאָגָה וּמְצוּקָה, וּפְרֹשׂ עָלַי מִקְלַט שָׁלוֹם, בְּרָכָה וְרַחֲמִים.\nאֵין אֱלוֹהַּ מִבַּלְעָדֶיךָ, לְךָ הַמַּלְכוּת וּלְךָ הַתְּהִלָּה, וְאַתָּה עַל כָּל דָּבָר כֹּל יָכוֹל. אָמֵן.",
