          "he": "ה' עֻזִּי וּמָגִנִּי, בּוֹ בָטַח לִבִּי וְנֶעֱזָרְתִּי.\nגַּם כִּי אֵלֵךְ בְּגֵיא צַלְמָוֶת לֹא אִירָא רָע כִּי אַתָּה עִמָּדִי.\nחַזֵּק אֶת רוּחִי בְּשָׁעָה זוֹ שֶׁל נִסָּיוֹן וּמַבְחָן, חַדֵּשׁ אֶת אֱמוּנָתִי וְהֱיֵה לִי לְצוּר מָעוֹז וּלְעֶזְרָה בְּצָרוֹת. אָמֵן.",
          "hi": "मैं क्षमा करता हूं और अपने आप को सभी पीड़ाओं से मुक्त करता हूं। मेरा हृदय प्रेम और कृतज्ञता का स्वच्छ झरना बन जाता है।",
          "zh": "我原谅自己并将自己从所有痛苦中解放出来。我的心变成一股爱与感恩的洁净之泉。",
          "la": "Perdono et me libero de omne dolor. Mi cor se vuelve un manantial limpio de caritas et gratitud.",
          "ja": "私はすべての痛みを許し、自分を解放します。私の心は愛と感謝の清らかな泉になります。",
          "bn": "আমি ক্ষমা করি এবং সমস্ত ব্যথা থেকে নিজেকে মুক্ত করি। আমার হৃদয় ভালবাসা এবং কৃতজ্ঞতার একটি পরিষ্কার বসন্ত হয়ে ওঠে।",
          "id": "Saya memaafkan dan membebaskan diri saya dari semua rasa sakit. Hatiku menjadi sumber cinta dan syukur yang bersih.",
