          "bn": "ইউক্যারিস্টিক যীশু, আমাকে আমার প্রতিবেশীকে ভালবাসতে শেখান যেমন আপনি আমাকে ভালবাসেন। আমার অহংকার ধুয়ে ফেলুন এবং আমার আত্মাকে পবিত্রতা এবং শান্তিতে পূর্ণ করুন। আমীন।",
          "id": "Yesus Ekaristi, ajari aku untuk mencintai sesamaku seperti Engkau mencintaiku. Basuhlah harga diriku dan penuhi jiwaku dengan kesucian dan kedamaian. Amin.",
          "ur": "یوکرسٹک یسوع، مجھے اپنے پڑوسی سے پیار کرنا سکھائیں جیسا کہ آپ نے مجھ سے پیار کیا ہے۔ میرے غرور کو دھو دے اور میری روح کو پاکیزگی اور سکون سے بھر دے۔ آمین۔",
          "sw": "Yesu wa Ekaristi, nifundishe kumpenda jirani yangu kama ulivyonipenda mimi. Osha kiburi changu na ujaze roho yangu kwa usafi na amani. Amina."
