          "bn": "আপনার পবিত্র ক্ষতগুলির মাধ্যমে, প্রভু, আমার ক্ষতগুলি নিরাময় করুন এবং আমাকে যারা অসন্তুষ্ট করেছেন তাদের ক্ষমা করার শক্তি দিন। তোমার হাতে আমি আমার জীবন সঁপে দিলাম। আমীন।",
          "id": "Melalui luka suci-Mu, Tuhan, sembuhkan lukaku dan beri aku kekuatan untuk mengampuni mereka yang telah menyakitiku. Ke tanganmu aku mempercayakan hidupku. Amin.",
          "ur": "اپنے مقدس زخموں کے ذریعے، خداوند، میرے زخموں کو مندمل کر اور مجھے ان لوگوں کو معاف کرنے کی طاقت دے جنہوں نے مجھے ناراض کیا ہے۔ آپ کے ہاتھ میں اپنی زندگی سونپتا ہوں۔ آمین۔",
