          "pt": "Aleluia! Senhor Ressuscitado, enche minha vida com a tua luz eterna. Que nada me separe do seu amor e que eu caminhe como filho da luz. Amém.",
          "it": "Alleluia! Signore risorto, riempi la mia vita della tua luce eterna. Che nulla mi separi dal tuo amore e che io possa camminare come un figlio della luce. Amen.",
          "de": "Alleluja! Auferstandener Herr, erfülle mein Leben mit Deinem ewigen Licht. Möge mich nichts von deiner Liebe trennen und möge ich als Kind des Lichts wandeln. Amen.",
          "ru": "Аллилуия! Воскресший Господь, наполни мою жизнь Своим вечным светом. Пусть ничто не отделяет меня от Твоей любви, и пусть я хожу как дитя света. Аминь.",
          "ar": "هللويا! أيها الرب القائم من بين الأموات،  املأ حياتي بنورك الأبدي. لا يجوز أن يفصلني شيء عن حبك،  وأسير كطفل نور. آمين.",
          "he": "ה' עֻזִּי וּמָגִנִּי, בּוֹ בָטַח לִבִּי וְנֶעֱזָרְתִּי.\nגַּם כִּי אֵלֵךְ בְּגֵיא צַלְמָוֶת לֹא אִירָא רָע כִּי אַתָּה עִמָּדִי.\nחַזֵּק אֶת רוּחִי בְּשָׁעָה זוֹ שֶׁל נִסָּיוֹן וּמַבְחָן, חַדֵּשׁ אֶת אֱמוּנָתִי וְהֱיֵה לִי לְצוּר מָעוֹז וּלְעֶזְרָה בְּצָרוֹת. אָמֵן.",
