          "zh": "哈利路亚！复活的主，请用你永恒的光充满我的生命。愿没有什么能将我与你的爱分开，愿我像光明之子一样行走。阿门。",
          "la": "¡Aleluya! Dominus resucitado, llena mi vita cum tu lux eterna. Que nada me aparte de tu caritas et qui camine sicut Filius lux. Amen.",
          "ja": "アレルヤ！復活した主よ、私の人生をあなたの永遠の光で満たしたまえ。私をあなたの愛から引き離すものは何もなく、私が光の子として歩むことができますように。アーメン。",
          "bn": "অ্যালেলুইয়া ! জেগে ওঠো প্রভু, তোমার অনন্ত আলো দিয়ে আমার জীবন পূর্ণ কর। কিছুই যেন আমাকে তোমার ভালোবাসা থেকে আলাদা না করে এবং আমি যেন আলোর সন্তান হয়ে চলতে পারি। আমীন।",
          "id": "Haleluya! Tuhan Yang Bangkit, penuhi hidupku dengan cahaya abadi-Mu. Semoga tidak ada yang memisahkanku dari cintamu dan semoga aku berjalan sebagai anak terang. Amin.",
          "ur": "الیلیویا! جی اٹھے خُداوند، میری زندگی کو اپنی ابدی روشنی سے بھر دے۔ کوئی چیز مجھے آپ کی محبت سے الگ نہ کرے اور میں روشنی کے بچے کی طرح چلوں۔ آمین۔",
          "sw": "Aleluya! Bwana mfufuka, yajaze maisha yangu na nuru yako ya milele. Usinitenganishe na upendo wako na nitembee kama mtoto wa nuru. Amina."
