      "hi": "भविष्यद्वक्ता दानिय्येल से प्रेरित 21 दिवसीय उपवास, शरीर को शुद्ध करने, ईश्वर की वाणी सुनने और आत्मिक विजय प्राप्त करने हेतु।",
      "zh": "受先知但以理启发的21天禁食与祈祷周期，旨在洁净身心、敏锐倾听天主圣言并在属灵世界赢得得胜。",
