      "bn": "ভাববাদী দানিয়েল দ্বারা অনুপ্রাণিত ২১ দিনের সমর্পণ, যা দেহকে পরিশুদ্ধ করে এবং ঈশ্বরের বাণী শুনে আত্মিক বিজয় আনে।",
      "id": "Dua puluh satu hari pengudusan terinspirasi oleh Nabi Daniel untuk detoksifikasi tubuh, menajamkan pendengaran pada suara Tuhan, dan meraih kemenangan rohani.",
