      "he": "תפילת פתיחה: בשם האל הכל יכול, נקדיש רגעים קדושים אלה ביראה ובלב תמים לתפילה ולבקשת רחמים.",
      "hi": "प्रारंभिक प्रार्थना: सर्वशक्तिमान ईश्वर के पवित्र नाम में, हम पूर्ण श्रद्धा और विश्वास के साथ इस पावन समय को समर्पित करते हैं।",
